<script lang="ts">
	import Button from "../ui/Button.svelte";
	import Icon from "../ui/Icon.svelte";
	import { t } from "../../lib/i18n";

	/**
	 * Ephemeral follow-up prompt suggestions generated by the system model under the latest completed assistant reply.
	 * Click sends the suggestion directly; Shift+click fills the composer for editing before send.
	 */
	let {
		suggestions,
		disabled = false,
		onpick,
	}: {
		suggestions: string[];
		disabled?: boolean;
		onpick: (text: string, fillOnly: boolean) => void;
	} = $props();
</script>

{#if suggestions.length > 0}
	<div class="followups" role="group" aria-label={t("추천 후속 질문")}>
		{#each suggestions as text (text)}
			<Button
				size="sm"
				class="followup-btn"
				{disabled}
				title={t("클릭해 바로 보내기 · Shift+클릭으로 입력창에 채우기")}
				onclick={(e) => onpick(text, e.shiftKey)}
			>
				<span class="ficon" aria-hidden="true"><Icon name="arrow-right" /></span>
				<span class="ftext">{text}</span>
			</Button>
		{/each}
	</div>
{/if}

